import React, { FC, useEffect, useState } from 'react';
import './CartPage.scss';
import { useDispatch, useSelector } from "react-redux";
import { AppDispatch, RootState } from "../../../store/store.config";
import { getCart } from "../../../store/cartSlice";
import CartServices from "../../../services/CartServices";
import { ICart } from "../../../interfaces/commonInterfaces";
import { Link } from "react-router-dom";
import reminderPhoto from "../../../assets/reminder.svg";

const CartPage: FC = () => {
    const { cart } = useSelector((state: RootState) => state.cartReducer);
    const dispatch = useDispatch<AppDispatch>();
    const [quantity, setQuantity] = useState<number>();

    useEffect(() => {
        dispatch(getCart()).then();
    }, [dispatch]);

    useEffect(() => {
        console.log(cart);
    }, [cart]);

    const handleItemDelete = (e: React.MouseEvent<HTMLButtonElement>, id: string) => {
        e.preventDefault();
        CartServices.removeFromCart(id).then(() => dispatch(getCart()));
    }

    const handleItemEdit = (e: React.MouseEvent<HTMLButtonElement>, id: string, gap: number) => {
        e.preventDefault();
        const item = cart?.find(item => item.reminderId === +id);
        if (item) {
            setQuantity(item.quantity + gap);
            CartServices.updateCart({ ...item, quantity: item.quantity + gap }).then(() => dispatch(getCart()));
        }
        setQuantity(0);
    }

    return (
        <section className={"cart"}>
            <h1>Your cart</h1>
            <div className={"cart-items"}>
                {cart && ( // Ensure cart is not null or undefined
                    cart.map((item: ICart, key = item.id) => (
                        <div key={key} className={"cart-item"}>
                            <Link to={`/reminders/${item.reminderId}`}><img src={reminderPhoto}
                                                                            alt={`${item.reminderId}`}/></Link>
                            <div className={"cart-item-info"}>
                                <h3>{item.reminderId}</h3>
                                <p>Priority: {item.priority}</p>
                            </div>
                            <div className={"cart-item-actions"}>
                                <button className={"quantity-button"}
                                        onClick={(e) => handleItemEdit(e, item.reminderId.toString(), 1)}>+
                                </button>
                                <h3>{item.quantity}</h3>
                                <button className={"quantity-button"}
                                        onClick={(e) => handleItemEdit(e, item.reminderId.toString(), -1)}>-
                                </button>
                            </div>
                            <button className={"delete-button"}
                                    onClick={(e) => handleItemDelete(e, item.reminderId.toString())}>x
                            </button>
                        </div>
                    ))
                )}
            </div>
        </section>
    );
};

export default CartPage;
